spec.query:
source = wazuh-states-vulnerabilities-*
| where like(`agent.name`, '$agent')
| eval severity = if(isnull(`vulnerability.severity`), 'Unknown',
    if(`vulnerability.severity` = '', 'Unknown', `vulnerability.severity`))
| stats count() as vulnerabilities by severity
| eval severity_order = if(severity = 'Critical', 1,
    if(severity = 'High', 2,
    if(severity = 'Medium', 3,
    if(severity = 'Low', 4, 5))))
| fields severity, vulnerabilities, severity_order
